BEGIN TRANSACTION;
CREATE TABLE aliases (
 alias_code TEXT PRIMARY KEY, alias_name TEXT NOT NULL, modality_scope TEXT,
 maps_to_category TEXT, physiological_decision_role TEXT, note TEXT);
CREATE TABLE limiters (
 limiter_code TEXT PRIMARY KEY, limiter_name TEXT NOT NULL, family TEXT NOT NULL,
 physiology_domain TEXT NOT NULL, description TEXT, selection_note TEXT);
CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE modalities (
 modality_code TEXT PRIMARY KEY, modality_name TEXT NOT NULL, aliases TEXT,
 distance_native INTEGER NOT NULL DEFAULT 0, notes TEXT);
CREATE TABLE monitoring_rules (
 monitoring_id INTEGER PRIMARY KEY AUTOINCREMENT, signal TEXT NOT NULL, operator TEXT NOT NULL,
 reference_source TEXT NOT NULL, runtime_method TEXT NOT NULL, unit TEXT, phase TEXT,
 success_condition TEXT, failure_condition TEXT, important_rule TEXT);
CREATE TABLE rule_modalities (
 rule_id TEXT NOT NULL, modality_code TEXT NOT NULL,
 PRIMARY KEY(rule_id, modality_code),
 FOREIGN KEY(rule_id) REFERENCES training_rules(rule_id),
 FOREIGN KEY(modality_code) REFERENCES modalities(modality_code));
CREATE TABLE sources (
 source_id TEXT PRIMARY KEY, title TEXT NOT NULL, source_type TEXT, author_or_org TEXT,
 year TEXT, url TEXT, file_name TEXT, use_in_engine TEXT, evidence_level TEXT);
CREATE TABLE training_rules (
 rule_id TEXT PRIMARY KEY, limiter_code TEXT NOT NULL, adaptation_target TEXT,
 mechanism_target TEXT, zone TEXT NOT NULL, expected_rpe_work TEXT, expected_rpe_session TEXT,
 training_type TEXT, format TEXT, work_range TEXT, distance_range_optional TEXT, recovery_range TEXT,
 duration_category TEXT, relevance TEXT, classification_tags TEXT, monitor_primary TEXT,
 success_pattern TEXT, failure_pattern TEXT, progression TEXT, evidence_level TEXT, source TEXT,
 progression_rule TEXT, success_rule TEXT, failure_rule TEXT, monitor_rule_1 TEXT,
 monitor_rule_2 TEXT, monitor_rule_3 TEXT, threshold_source TEXT, threshold_calculation TEXT,
 runtime_value_type TEXT, progression_gate TEXT, regression_gate TEXT, work_power_rule TEXT,
 work_hr_rule TEXT, dynamic_crosscheck_rule TEXT, notes TEXT,
 FOREIGN KEY(limiter_code) REFERENCES limiters(limiter_code));
CREATE TABLE training_types (
 training_type_code TEXT PRIMARY KEY, training_type_name TEXT NOT NULL, category TEXT NOT NULL,
 typical_work TEXT, typical_recovery TEXT, typical_rpe TEXT, primary_physiological_targets TEXT,
 can_be_primary_for TEXT, should_not_be_auto_assigned_to TEXT, modality_notes TEXT,
 evidence_level TEXT, source_ids TEXT);
CREATE TABLE workout_library (
 workout_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, modality_code TEXT NOT NULL,
 rule_id TEXT, training_type_code TEXT, zone TEXT, work_description TEXT,
 work_duration_s INTEGER, recovery_duration_s INTEGER, repeats INTEGER, distance_m REAL,
 work_power_min REAL, work_power_max REAL, work_hr_min REAL, work_hr_max REAL,
 rpe_work_min REAL, rpe_work_max REAL, tags TEXT, source TEXT, is_user_added INTEGER NOT NULL DEFAULT 0,
 active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP,
 updated_at TEXT DEFAULT CURRENT_TIMESTAMP, notes TEXT,
 FOREIGN KEY(modality_code) REFERENCES modalities(modality_code),
 FOREIGN KEY(rule_id) REFERENCES training_rules(rule_id),
 FOREIGN KEY(training_type_code) REFERENCES training_types(training_type_code));
CREATE INDEX idx_rules_limiter_zone ON training_rules(limiter_code, zone);
CREATE INDEX idx_rules_modality ON rule_modalities(modality_code);
CREATE INDEX idx_library_modality ON workout_library(modality_code);
CREATE INDEX idx_library_rule ON workout_library(rule_id);
DELETE FROM "sqlite_sequence";
COMMIT;
