INSERT INTO "aliases" VALUES('UT2','UT2','row,ski','CONT/Z1','alias','Nome de treinamento; não é chave fisiológica.');
INSERT INTO "aliases" VALUES('UT1','UT1','row,ski','CONT/Z1-Z2','alias','Nome de treinamento; limites variam.');
INSERT INTO "aliases" VALUES('AT','AT','row,ski','THR/Z2','alias','Alias de threshold; fronteiras variam.');
INSERT INTO "aliases" VALUES('TR','TR / Transport','row,ski','HIIT/VO2/short','alias','Não assumir automaticamente VO₂.');
INSERT INTO "aliases" VALUES('AN','AN','row,ski','SIT/RST','alias','Esforços curtos; não usar como chave do limitador.');
INSERT INTO "aliases" VALUES('TECH','TECH / técnica','row,ski','CONT/Z1','support','Sessão técnica; objetivo pode ser coordenação, não limitador cardiorrespiratório.');
INSERT INTO "limiters" VALUES('CD','Limitação de entrega (cardíaco)','cardiaco','entrega','Limitação de entrega/central: o estímulo procura aumentar ou sustentar a capacidade de fornecer O₂ ao trabalho.','D1/D2/D3 e trabalhos de alta intensidade podem ser usados conforme zona e padrão observado; não confundir com eixo 5-1-5 de Utilização/Fornecimento.');
INSERT INTO "limiters" VALUES('RD','Limitação respiratória','respiratorio','respiratorio','Limitação ventilatória/respiratória: o estímulo procura melhorar controle ventilatório, tolerância e capacidade dos músculos respiratórios.','Threshold/VO₂ podem ser respiratórios quando RF/ventilação for o padrão dominante; IMT/isocapnia são complementares e não substituem o treino cíclico.');
INSERT INTO "limiters" VALUES('UT','Limitação de utilização','periferico','utilizacao','Limitação periférica/oxidativa: o estímulo procura aumentar a capacidade de utilizar O₂ e sustentar demanda periférica.','SmO₂ é sinal contextual; não inferir utilização apenas por SmO₂ isolada.');
INSERT INTO "limiters" VALUES('CO2','Limitação respiratória / tolerância ventilatória','respiratorio','respiratorio','Hipótese específica de alta demanda ventilatória/CO₂ quando sustentada pelos dados.','Usar apenas quando o padrão VST/MOXY suportar; não assumir pela etiqueta HIIT.');
INSERT INTO "limiters" VALUES('FR','Acúmulo de fadiga / recuperação limitada','fadiga','recuperacao','Estado de tolerância reduzida à carga; prioriza opções com menor custo interno e recuperação suficiente.','Não é um limitador fisiológico primário equivalente a entrega/respiratório/utilização; é uma condição de seleção.');
INSERT INTO "limiters" VALUES('ME','Limitação mecânica / coordenação','mecanica','mecanica','Limitação de execução/coordenação que pode mascarar a resposta fisiológica.','Priorizar controle técnico e carga que preserve o gesto.');
INSERT INTO "metadata" VALUES('schema_version','1.0');
INSERT INTO "metadata" VALUES('created','2026-09-27');
INSERT INTO "metadata" VALUES('purpose','Tabela mestre do Training Engine para seleção de opções de treino por modalidade e limitador fisiológico.');
INSERT INTO "metadata" VALUES('principle','O limitador/padrão fisiológico é a entrada; o nome do treino é classificação posterior. Watts e bpm do WORK são calculados em runtime.');
INSERT INTO "metadata" VALUES('dynamic_values','HR/RF/SmO2/potência/recovery não devem ser hard-coded quando dependem do atleta. O engine deve cruzar VST/MOXY sincronizados e, se não houver, a MOXY mais recente disponível.');
INSERT INTO "metadata" VALUES('user_choice','A aba Training apresenta opções; não decide automaticamente ''o que treinar agora''.');
INSERT INTO "metadata" VALUES('execution_evaluation','A avaliação de execução pertence a outra área da aplicação e não faz parte desta tabela mestre.');
INSERT INTO "modalities" VALUES('bike','Bike','cycling,bicicleta',0,'Potência em W; distância opcional.');
INSERT INTO "modalities" VALUES('row','Row','remo,rowing,rowing erg,erg',1,'Pode usar distância/split como unidade nativa.');
INSERT INTO "modalities" VALUES('ski','Ski','ski erg,skiing',1,'UT2/UT1/AT/TR/AN são aliases; não são chaves fisiológicas.');
INSERT INTO "modalities" VALUES('run','Run','corrida,running',1,'Pode usar pace/distância; potência pode ser derivada pelo modelo individual.');
INSERT INTO "monitoring_rules" VALUES(1,'HR','range/max/trend','histórico comparável da mesma modalidade e zona; BP1/BP2 como referência','percentis/mediana + limites individuais','bpm','WORK / final do WORK','HR dentro da faixa individual e sem drift precoce','HR acima do padrão/teto ou drift desproporcional','Não usar valor universal quando há histórico suficiente.');
INSERT INTO "monitoring_rules" VALUES(2,'RF','range/max/trend','histórico comparável + VST','percentis/mediana + tendência intra-WORK/inter-WORK','resp/min','WORK / início e final / recovery','RF dentro da faixa esperada e sem acumulação precoce','RF começa progressivamente mais alta ou deriva muito para a mesma potência','É sinal primário para regras respiratórias.');
INSERT INTO "monitoring_rules" VALUES(3,'SmO2','range/trend','MOXY comparável da mesma modalidade/músculo','tendência e distribuição individual; nunca regra universal isolada','%','WORK / recovery','padrão compatível com a resposta histórica','queda/recuperação incompatível com padrão multimétrico','SmO2 não distingue sozinho extração de alteração de fluxo.');
INSERT INTO "monitoring_rules" VALUES(4,'RPE','range','histórico de execução + expectativa da regra','comparar RPE com potência/HR/RF e sessão','1–10','WORK / sessão','RPE dentro da faixa esperada para a carga','RPE desproporcional para a carga','Não substituir sinais fisiológicos por RPE isolado.');
INSERT INTO "monitoring_rules" VALUES(5,'Power','range/trend','BP1/BP2 + eFTP/CP/Pmax + histórico','calcular faixa de WORK em runtime','W','WORK','potência dentro da faixa com estabilidade de repetição','queda de potência ou incapacidade de manter faixa','Sempre usar modalidade e contexto.');
INSERT INTO "monitoring_rules" VALUES(6,'recovery','recovery/trend','VST/MOXY + histórico entre WORKs','tempo/retorno relativo ao padrão individual','s/min','entre WORKs','retorno compatível com o padrão','recovery progressivamente pior','Parte do mecanismo-alvo em HIIT/VO2/RST.');
