INSERT INTO "sources" VALUES('S15','Tabela Taxonomia Treinos V2','documento do projeto','—','2026','','Tabela_Taxonomia_Treinos_V2.csv','Taxonomia de VO₂/threshold/HIIT/SIT/RST/over-under','B');
INSERT INTO "training_rules" VALUES('CD-Z1-01','CD','Suportar volume e tolerância cardiovascular aeróbia','Exposição aeróbia com baixo custo por unidade de tempo','Z1','3–5','3–5','Contínuo','Contínuo','20–60 min','Opcional: converter pela velocidade/split individual','—','Longo/Muito longo','principal','Contínuo; Z1','HR · RPE · RF · recovery','HR/RF estáveis e recuperação rápida','Drift precoce ou RPE desproporcional','Aumentar tempo total; depois volume; não subir zona e volume simultaneamente','B','Revisões de distribuição de intensidade','Aumentar tempo total; depois volume; não subir zona e volume simultaneamente | Tempo total: 20→40→60 min; só depois aumentar volume semanal.','Manter HR/RF dentro da faixa individual observada para Z1 e RPE dentro da faixa esperada; sem drift precoce.','Reduzir/encerrar progressão se HR ou RF ultrapassar a faixa individual de referência ou RPE ficar acima do esperado para a carga.','HR: faixa histórica Z1 / limite superior individual','RF: faixa histórica Z1 / limite superior individual','RPE: 3–5; recovery: retorno ao padrão individual','Histórico do atleta, mesma modalidade e zona; preferir sessões recentes comparáveis','Calcular faixa de referência por modalidade/zona a partir das sessões comparáveis; não usar número universal.','range/max','Só progredir tempo/volume se os indicadores permanecerem dentro da faixa individual.','Se houver divergência precoce ou recovery pior que o padrão, manter ou regredir a etapa.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('CD-Z2-01','CD','Aumentar tolerância cardiovascular em intensidade moderada-alta','Tempo sustentado próximo da transição aeróbia-alta','Z2','6–7','6–8','Threshold','Intervalado sustentado','2–4 × 8–15 min','Opcional: converter pela velocidade/split individual','3–6 min','Muito longo','principal','Threshold; Z2','HR · RF · RPE · recovery','Drift de HR/RF controlado ao longo dos blocos','Primeira divergência precoce ou recovery piora','Aumentar duração dos blocos; depois volume; potência só depois','B','Revisões de distribuição de intensidade','Aumentar duração dos blocos; depois volume; potência só depois | Bloco: 8→10→12→15 min; depois adicionar bloco; recovery permanece 3–6 min até estabilidade.','Durante cada WORK, HR/RF devem permanecer dentro da faixa individual de Z2; RPE 6–7 e drift controlado.','Se HR/RF ultrapassarem o limite superior individual ou RPE subir além do esperado para a potência, não aumentar carga.','HR: range histórico Z2','RF: range histórico Z2','RPE: 6–7; recovery: padrão individual entre blocos','Histórico Z2 comparável + BP1/BP2 existentes','Derivar limites de HR/RF por WORK ou bloco a partir do histórico comparável; usar BP1/BP2 apenas como referência de zona.','range/max/trend','Progredir duração/volume somente se drift e recovery permanecerem dentro do padrão.','Se primeira divergência ocorrer antes do padrão histórico, bloquear progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('CD-Z3-01','CD','Estimular capacidade cardiovascular central em alta intensidade','Exposição repetida a alto VO₂/alto débito cardíaco','Z3','8–9','7–9','VO₂ / HIIT','Intervalos médios','3–6 × 3–5 min','Opcional: converter pela velocidade/split individual','2–4 min','Médio','principal','VO₂; HIIT longo; Z3','HR · RF · RPE · recovery','Tempo de esforço de qualidade acumulado sem queda precoce','Queda de potência, RPE dispara ou recovery incompleto','Aumentar minutos totais de trabalho → depois reduzir recovery; não aumentar tudo junto','A','Revisão/meta-análise de adaptações cardiovasculares ao treino intervalado; meta-análises HIIT/SIT','Aumentar minutos totais de trabalho → depois reduzir recovery; não aumentar tudo junto | 3×3→4×4→5×4→6×4 min; depois ajustar recovery dentro da faixa.','Permitir HR/RF elevados, mas manter RPE 8–9 e potência dentro da faixa prescrita; recovery deve permanecer funcional.','Não deixar HR/RF/RPE ou queda de potência ultrapassarem o limite individual de qualidade definido pelo histórico.','HR: atingir a faixa alta individual esperada sem exceder o teto histórico comparável','RF: faixa alta individual; observar acúmulo entre WORKs','RPE: 8–9; recovery: mínimo/padrão individual','Histórico de Z3/VO2 da mesma modalidade','Derivar faixa/teto por sessão e WORK a partir dos valores históricos comparáveis; sem teto universal em bpm/RF/SmO2.','range/max/trend','Aumentar minutos totais mantendo qualidade antes de reduzir recovery.','Queda de potência, RPE acima do esperado ou recovery progressivamente pior bloqueia progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('RD-Z1-01','RD','Controle ventilatório e coordenação respiratória','Prática prolongada em baixa/moderada intensidade','Z1','3–5','3–5','Contínuo','Contínuo com foco respiratório','20–60 min','Opcional: converter pela velocidade/split individual','—','Longo/Muito longo','principal','Contínuo; Z1','RF · RPE · HR','RF estável e menor tendência de escalada para a mesma carga','RF deriva cedo ou RPE sobe sem aumento proporcional da carga','Aumentar tempo antes de intensidade; manter carga que permita controle ventilatório','B','Literatura de treinamento respiratório + material Ricci/Bouverot','Aumentar tempo antes de intensidade; manter carga que permita controle ventilatório | 30→45→60 min mantendo controle ventilatório.','RF deve permanecer na faixa individual de baixa intensidade e não apresentar subida precoce; HR acompanha a carga.','Se RF ultrapassar o limite individual ou RPE ficar desproporcional, reduzir carga/tempo.','RF: faixa histórica Z1','HR: faixa histórica Z1','RPE: 3–5; recovery: padrão individual','Histórico da modalidade + padrão cardiorrespiratório individual','Usar distribuição histórica de RF/HR em Z1; limites são calculados em runtime.','range/max/trend','Aumentar duração mantendo RF estável.','Drift precoce de RF/HR ou RPE desproporcional impede progressão.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('RD-Z2-01','RD','Tolerância ventilatória sustentada','Exposição repetida a ventilação elevada controlável','Z2','6–7','6–8','Threshold','Blocos sustentados','2–4 × 6–15 min','Opcional: converter pela velocidade/split individual','3–6 min','Muito longo','principal','Threshold; Z2','RF · HR · RPE · recovery','RF do início ao fim do bloco mais estável e recovery melhora','RF cresce muito dentro do bloco ou começa cada bloco mais alta','Aumentar duração do bloco → volume total → só então intensidade','B','Literatura de treinamento respiratório + distribuição de intensidade','Aumentar duração do bloco → volume total → só então intensidade | 6→8→10→12 min/bloco; depois adicionar bloco; só então intensificar.','RF pode subir com a carga, mas deve permanecer dentro da faixa individual de Z2 e sem divergência precoce; RPE 6–7.','Se RF começar cada WORK acima do padrão histórico ou crescer excessivamente dentro do WORK, não progredir.','RF: range histórico Z2','HR: range histórico Z2','RPE: 6–7; recovery entre WORKs','Histórico Z2 da mesma modalidade','Calcular faixa por WORK/bloco comparável; usar percentis/mediana histórica ou limites individuais já existentes, sem valores universais.','range/trend','Primeiro aumentar duração do WORK; depois volume.','Divergência precoce ou recovery insuficiente bloqueia progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('RD-Z3-01','RD','Tolerância a alta demanda ventilatória','Exposição curta/média a alta ventilação com recuperação suficiente','Z3','8–9','7–9','VO₂ / HIIT','Intervalos médios','3–6 × 2–5 min','Opcional: converter pela velocidade/split individual','2–5 min','Curto/Médio','principal','VO₂; HIIT; Z3','RF · HR · RPE · recovery','RF alta mas controlada, sem divergência precoce','RF entra muito alta ou acumula entre repetições','Aumentar trabalho total mantendo qualidade; depois ajustar recovery','B','Literatura de treinamento respiratório + HIIT','Aumentar trabalho total mantendo qualidade; depois ajustar recovery | 2→3→4→5 min/bloco; depois aumentar total de trabalho sem antecipar divergência de RF.','RF deve atingir nível alto compatível com Z3, mas sem iniciar cada repetição progressivamente mais alta; RPE 8–9.','Se RF acumular entre repetições ou RPE disparar para a mesma potência, aumentar recovery ou reduzir volume.','RF: faixa alta histórica Z3','HR: faixa alta histórica Z3','RPE: 8–9; recovery: retorno individual esperado','Histórico de Z3/HIIT + verificações VST','Derivar faixa/teto e tendência de RF/HR por WORK comparável.','range/max/trend/recovery','Aumentar tempo total mantendo a qualidade respiratória.','Acúmulo precoce de RF ou recovery pior impede progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('RM-Z1-01','RD','Endurance dos músculos respiratórios','Exposição sustentada de baixa/moderada intensidade + IMT separado quando indicado','Z1','3–5','3–5','Contínuo','Contínuo + IMT complementar','30–90 min','Opcional: converter pela velocidade/split individual','—','Muito longo','principal','Z1; Contínuo; IMT','RF · RPE · HR · recovery','Menor custo ventilatório para a mesma carga ao longo do tempo','RF/RPE pioram sem mudança de carga','Aumentar duração aeróbia; IMT segue protocolo próprio e separado','B','Meta-análise de RMT','Aumentar duração aeróbia; IMT segue protocolo próprio e separado | 30→45→60→90 min; IMT separado segue protocolo próprio.','RF/RPE devem permanecer baixos e estáveis para a carga; qualquer IMT complementar segue seu protocolo separado.','Não aumentar volume se RF/RPE/HR estiverem acima do padrão individual.','RF: faixa histórica Z1','RPE: 3–5','HR/recovery: padrão individual','Histórico Z1 + protocolo específico de IMT','Limites aeróbios derivados do histórico; parâmetros de IMT não são inventados pelo engine.','range/max','Aumentar tempo aeróbio antes de elevar intensidade.','Piora de resposta interna bloqueia progressão.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','Treino cíclico com IMT complementar; IMT não é embutido como execução da sessão.');
INSERT INTO "training_rules" VALUES('RM-Z2-01','RD','Força/endurance respiratória funcional durante exercício','Repetição de esforços moderado-altos com controle de RF','Z2','6–7','6–8','Intervalado','Médio intervalado','3–6 × 3–8 min','Opcional: converter pela velocidade/split individual','2–5 min','Médio','possível','HIIT curto/médio; Z2','RF · RPE · HR · recovery','Menor drift de RF entre blocos e recovery mais rápido','RF inicia cada repetição mais alta','Aumentar número/tempo total de trabalho antes de elevar intensidade','B','Literatura respiratória + HIIT','Aumentar número/tempo total de trabalho antes de elevar intensidade | 3×3→4×4→5×5→6×5 min; qualidade de RF antes de aumentar intensidade.','RF permanece controlável e RPE 6–8, com recovery suficiente entre blocos.','Se RF iniciar cada bloco mais alta ou recovery piorar progressivamente, não aumentar intensidade.','RF: range histórico Z2','HR: range histórico Z2','RPE: 6–8; recovery individual','Histórico Z2 + VST','Derivar limites de RF/HR/RPE de sessões comparáveis.','range/trend/recovery','Aumentar volume de trabalho antes de intensidade.','Divergência respiratória precoce bloqueia progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('CO2-Z3-01','RD','Tolerância a elevada demanda de CO₂/drive ventilatório','Exposição controlada a alta ventilação sem falha precoce','Z3','8–10','8–9','HIIT','Intervalos curtos/médios','4–10 × 1–4 min','Opcional: converter pela velocidade/split individual','2–4 min','Curto/Médio','limiar','HIIT; Z3','RF · RPE · recovery','RF recupera entre repetições e não inicia cada bloco excessivamente alta','Acúmulo progressivo de RF ou queda de qualidade','Primeiro aumentar recuperação/qualidade → depois volume → só então reduzir recovery','C','Hipótese individualizada; literatura respiratória não permite tratar como regra universal','Primeiro aumentar recuperação/qualidade → depois volume → só então reduzir recovery | Primeiro melhorar recuperação/qualidade; depois adicionar repetições; por fim reduzir recovery moderadamente.','RF alta, porém com recuperação suficiente entre WORKs; RPE 8–9.','Se RF acumular de WORK para WORK ou recovery ficar abaixo do padrão individual, não progredir.','RF: teto histórico comparável','RPE: 8–9','Recovery: padrão individual entre WORKs','Histórico VST/HIIT; hipótese individual','Usar somente limites observados; não atribuir valor universal de RF/CO2 sem medida direta.','max/trend/recovery','Primeiro melhorar recovery/qualidade; depois volume.','Acúmulo respiratório precoce bloqueia progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','Regra condicional: só aparece quando o padrão ventilatório/CO₂ for sustentado pelos dados.');
INSERT INTO "training_rules" VALUES('UT-Z1-01','UT','Capacidade oxidativa periférica e tolerância a volume','Alto volume aeróbio favorecendo estímulo periférico','Z1','3–5','3–5','Contínuo','Contínuo','30–90 min','Opcional: converter pela velocidade/split individual','—','Muito longo','principal','Contínuo; Z1','SmO₂ · RPE · HR · recovery','Carga sustentável com recovery adequado; sem deterioração periférica precoce','Fadiga local desproporcional ou recovery piora','Aumentar duração/volume semanal antes de subir zona','B','Revisões de treinamento de resistência e intervalos','Aumentar duração/volume semanal antes de subir zona | 30→45→60→75→90 min antes de subir zona.','SmO2/RPE/HR devem permanecer dentro do padrão individual de Z1; não exigir uma direção fixa de SmO2.','Não usar uma queda isolada de SmO2 como gatilho; se a resposta periférica e RPE divergirem do padrão histórico, não progredir.','SmO2: faixa histórica comparável','RPE: 3–5','HR/recovery: faixa individual Z1','Histórico de SmO2 da mesma modalidade/músculo quando disponível','Derivar faixa e tendência de SmO2 de sessões comparáveis; interpretar junto de HR/RPE/potência.','range/trend','Aumentar duração se a resposta periférica permanecer no padrão.','Divergência multimétrica bloqueia progressão.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('UT-Z2-01','UT','Extração/utilização periférica sob carga sustentada','Tempo em intensidade moderada-alta com demanda metabólica estável','Z2','6–7','6–8','Threshold','Blocos sustentados','2–4 × 8–15 min','Opcional: converter pela velocidade/split individual','3–6 min','Muito longo','principal','Threshold; Z2','SmO₂ · RPE · HR · recovery','Resposta de SmO₂ e RPE mais estável para a mesma potência','Queda periférica muito precoce + RPE desproporcional','Aumentar duração dos blocos → total de trabalho; não usar SmO₂ isoladamente','B','Revisões de treinamento de resistência e intervalos','Aumentar duração dos blocos → total de trabalho; não usar SmO₂ isoladamente | Aumentar duração dos blocos; depois total de trabalho; intensidade por último.','Permitir resposta de SmO2 compatível com a carga, mas permanecer dentro do padrão histórico para Z2; RPE 6–8.','Não impor ''SmO2 mínimo universal''. Interromper progressão se SmO2/RPE/HR divergirem conjuntamente do padrão individual.','SmO2: faixa/tendência histórica Z2','HR: range histórico Z2','RPE: 6–8; recovery individual','Histórico MOXY/VST da modalidade e músculo','Calcular faixa/tendência a partir de WORKs comparáveis; SmO2 é contextual, não prova isolada de extração.','range/trend','Aumentar tempo/volume mantendo padrão multimétrico.','Queda periférica muito precoce acompanhada de piora de RPE/HR bloqueia progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('UT-Z3-01','UT','Capacidade oxidativa/periférica em alta demanda','Intervalos de alta intensidade elevando demanda central e periférica','Z3','8–9','7–9','HIIT / VO₂','Intervalos médios','3–6 × 3–5 min','Opcional: converter pela velocidade/split individual','2–4 min','Médio','principal','VO₂; HIIT; Z3','SmO₂ · HR · RF · RPE · recovery','Qualidade de potência mantida e resposta periférica sem deterioração precoce','Queda de potência e SmO₂/RPE pioram cedo','Aumentar tempo total de trabalho antes de reduzir recovery','A','Revisões de intervalos/VO₂','Aumentar tempo total de trabalho antes de reduzir recovery | 3×3→4×4→5×4→6×4 min; não reduzir recovery antes de manter qualidade.','Permitir alta demanda e queda de SmO2 compatível com o padrão individual, mantendo potência e RPE 8–9.','Não buscar um ''SmO2 mínimo'' fixo. Se a queda de SmO2 vier acompanhada de queda de potência ou RPE desproporcional, não progredir.','SmO2: tendência/faixa histórica Z3','Potência: manter dentro da faixa prescrita','RPE: 8–9; HR/RF/recovery individuais','Histórico MOXY/VST de Z3','Derivar limites e tendência do conjunto de sinais; não interpretar SmO2 isoladamente.','trend/range/max','Aumentar tempo total de trabalho antes de aumentar intensidade.','Queda de potência + divergência periférica bloqueia progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('PERF-Z3-01','UT','Capacidade de repetir esforços intensos com recuperação suficiente','Repetições curtas/médias com recuperação controlada','Z3','8–10','8–9','HIIT / RST','Short-HIIT / Repeated efforts','6–12 × 20 s–3 min','Opcional: distância equivalente individual; ex. 100–1000 m conforme modalidade e potência','1–4 min','Sprint/Curto','limiar','SIT/SIIT; RST; HIIT curto','RPE · HR · RF · recovery · potência','Qualidade das repetições e recuperação entre esforços melhoram','Queda acentuada de potência ou RPE dispara','Aumentar repetições mantendo qualidade → depois reduzir recovery modestamente','B','Revisões/meta-análises HIIT/SIT/RST','Aumentar repetições mantendo qualidade → depois reduzir recovery modestamente | Adicionar repetições mantendo potência; depois reduzir recovery modestamente.','Cada repetição deve permanecer dentro da faixa de potência e RPE 8–10, com recuperação individual suficiente.','Se a potência cair além do padrão histórico ou RPE subir sem manutenção da potência, aumentar recovery/reduzir volume.','Potência: faixa individual','RPE: 8–10','HR/RF/recovery: padrão individual','Histórico de esforços curtos/médios','Usar a distribuição histórica de potência/RPE/recovery para definir o limite de qualidade.','range/max/recovery','Aumentar repetições mantendo qualidade antes de reduzir recovery.','Queda de qualidade acima do padrão impede progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','SIT/RST é formato de alta intensidade; não assumir que seja o melhor estímulo para entrega ou respiratório sem evidência do padrão.');
INSERT INTO "training_rules" VALUES('FR-Z1-01','FR','Aumentar capacidade de sustentar volume com baixo custo','Volume aeróbio fácil com baixa carga interna','Z1','3–5','3–5','Contínuo','Contínuo fácil','30–90 min','Opcional: converter pela velocidade/split individual','—','Muito longo','principal','Z1; Contínuo','HR · RPE · recovery · wellness','RPE baixo e recovery normalizam sem aumento de drift','RPE/HR anormais para a carga habitual','Progressão conservadora do tempo total; não aumentar intensidade enquanto recovery piora','B','Revisões de distribuição de intensidade','Progressão conservadora do tempo total; não aumentar intensidade enquanto recovery piora | Aumentar volume fácil conservadoramente; intensidade fica estável se recovery piorar.','RPE 3–5, HR/RF dentro do padrão individual de Z1 e recovery normal.','Se RPE/HR estiverem elevados para a mesma carga ou recovery piorar, manter/reduzir volume.','HR: faixa histórica Z1','RF: faixa histórica Z1','RPE: 3–5; recovery individual','Histórico recente da modalidade','Calcular faixa individual de resposta interna em Z1.','range/max/recovery','Aumentar volume fácil progressivamente.','Qualquer piora persistente do recovery bloqueia progressão.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('FR-Z2-01','FR','Tolerância à carga moderada sem perda excessiva de recuperação','Blocos sustentados com recuperação suficiente','Z2','6–7','6–8','Intervalado','Over/Under leve ou threshold intervalado','2–4 × 6–12 min','Opcional: converter pela velocidade/split individual','3–6 min','Muito longo','possível','Threshold; Over/Under; Z2','HR · RF · RPE · recovery','Drift controlado e recovery entre blocos funcional','Recovery piora progressivamente e RPE sobe fora da relação com potência','Aumentar volume de trabalho; manter recovery até padrão estável antes de reduzir','B','Revisões de distribuição de intensidade','Aumentar volume de trabalho; manter recovery até padrão estável antes de reduzir | Aumentar total de trabalho; manter recovery até padrão estável; depois reduzir.','RPE 6–8, HR/RF dentro da faixa individual de Z2 e recovery funcional.','Se recovery piorar progressivamente ou HR/RF excederem o padrão para a carga, não aumentar volume/intensidade.','HR: range histórico Z2','RF: range histórico Z2','RPE: 6–8; recovery individual','Histórico Z2 + wellness/recovery','Derivar faixas de HR/RF/RPE/recovery da carga comparável.','range/trend/recovery','Aumentar volume antes de intensidade.','Recovery deteriorando bloqueia progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('FR-Z3-01','FR','Tolerância a esforços repetidos de alta intensidade','Repetições de alta intensidade com recuperação deliberadamente definida','Z3','8–10','8–9','HIIT / RST','Intervalado curto/médio','6–12 × 20 s–3 min','Opcional: distância equivalente individual; ex. 100–1000 m conforme modalidade e potência','1–5 min','Sprint/Curto/Médio','limiar','SIT/SIIT; RST; HIIT','RPE · HR · RF · recovery · potência','Recuperação entre repetições melhora sem perda de qualidade','Potência cai muito ou recovery fica progressivamente incompleto','Qualidade → repetições → redução de recovery','B','Revisões/meta-análises HIIT/SIT/RST','Qualidade → repetições → redução de recovery | Qualidade→repetições→redução de recovery; não alterar as três variáveis juntas.','RPE 8–9/10, potência dentro da faixa e recovery entre repetições conforme padrão individual.','Se potência cair ou recovery ficar progressivamente incompleto, não aumentar carga.','Potência: faixa individual','RPE: 8–9/10','HR/RF/recovery: padrão histórico Z3','Histórico Z3/HIIT','Derivar limite de qualidade pela distribuição histórica das repetições.','range/max/recovery','Qualidade → repetições → recovery.','Queda de qualidade ou recovery bloqueia progressão.','WORK: faixa de potência individual da Z3 (BP2 → teto de trabalho individual derivado de histórico/eFTP/CP/Pmax conforme modalidade).','WORK HR: faixa alta histórica individual da mesma modalidade/Z3; observar teto e tendência entre WORKs.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('ME-Z1-01','ME','Economia e coordenação do gesto em baixa carga interna','Alto volume técnico com baixa fadiga','Z1','3–5','3–5','Contínuo','Contínuo técnico','20–60 min','Opcional: converter pela velocidade/split individual','—','Longo/Muito longo','principal','Contínuo; Z1','RPE · HR · RF · técnica','Mesma potência/ritmo com menor custo interno ou maior estabilidade','Técnica degrada ou RPE sobe sem aumento externo','Aumentar duração mantendo técnica; depois adicionar blocos moderados','B','Literatura geral de endurance/coordenação','Aumentar duração mantendo técnica; depois adicionar blocos moderados | Aumentar duração mantendo técnica; depois adicionar blocos moderados.','RPE 3–5, HR/RF estáveis e técnica preservada.','Se técnica degradar ou RPE/HR aumentarem sem aumento de carga, reduzir duração.','RPE: 3–5','HR/RF: faixa histórica Z1','Técnica: padrão individual','Histórico da modalidade + observação técnica','Derivar limites internos do histórico e critérios técnicos disponíveis.','range/max','Aumentar duração mantendo técnica.','Degradação técnica precoce bloqueia progressão.','WORK: faixa de potência individual da Z1 (limite inferior histórico comparável → BP1/limite Z1). Se eFTP/CP for necessário como fallback, usar o modelo individual.','WORK HR: faixa histórica individual da mesma modalidade/Z1; fallback para zonas HR individuais.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_rules" VALUES('ME-Z2-01','ME','Manter técnica sob carga moderada-alta','Exposição repetida ao gesto em carga que ainda permite controle','Z2','6–7','6–8','Intervalado','Blocos médios','3–6 × 3–8 min','Opcional: converter pela velocidade/split individual','2–5 min','Médio','principal','Z2; HIIT médio','RPE · HR · RF · técnica','Técnica permanece estável até o fim do bloco','Degradação técnica precede queda de potência','Aumentar duração mantendo técnica antes de elevar intensidade','B','Literatura geral de endurance/intervalos','Aumentar duração mantendo técnica antes de elevar intensidade | Aumentar duração do bloco mantendo técnica; intensidade só depois.','RPE 6–8, HR/RF dentro da faixa individual e técnica preservada até o fim do WORK.','Se técnica degradar antes do final ou RPE subir desproporcionalmente, não aumentar intensidade.','RPE: 6–8','HR/RF: range histórico Z2','Técnica: critério individual','Histórico da modalidade','Derivar limites internos e de execução de sessões comparáveis.','range/trend','Aumentar duração do WORK antes de intensidade.','Degradação técnica precoce bloqueia progressão.','WORK: faixa de potência individual da Z2 (BP1 → BP2), refinada pelo histórico de sessões comparáveis.','WORK HR: faixa histórica individual da mesma modalidade/Z2; cruzar com BP1/BP2 quando disponível.','Cruzar WORK de VST/MOXY sincronizado; se não houver VST, usar a MOXY mais recente da modalidade quando disponível; comparar potência, HR, RF, SmO₂, RPE e recovery sem deixar uma variável isolada decidir.','');
INSERT INTO "training_types" VALUES('CONT','Contínuo','endurance','20–180 min ou conforme regra','—','3–5 / 6–7','Volume aeróbio, recuperação, controle ventilatório','CD,RD,UT,FR,ME','não atribuir mecanismo apenas pelo nome','Bike/Row/Ski/Run','B','S01,S06,S07,S08');
INSERT INTO "training_types" VALUES('THR','Threshold / Limiar','threshold','8–20 min por peça ou contínuo','~30 s–6 min em formatos intervalados, conforme regra','6–7','Sustentar intensidade próxima do limiar; transporte/uso de lactato e tolerância sustentada','CD,RD,UT','não classificar automaticamente como respiratório','Bike/Row/Ski/Run; Row/Ski podem usar AT','B','S01,S06,S08');
INSERT INTO "training_types" VALUES('VO2','VO₂ / VO₂max','high_aerobic','2–10 min por peça','aprox. semelhante ao WORK em B2; varia por protocolo','8–9','Acumular tempo em alta fração do VO₂; pode servir à entrega central ou à tolerância ventilatória conforme padrão','CD,RD,UT','não usar o nome para decidir o limitador','Bike/Row/Ski/Run','A-B','S01,S02,S03,S04,S08');
INSERT INTO "training_types" VALUES('HIIT','HIIT','umbrella','15 s–10 min conforme formato','definida pelo protocolo','6–10','Categoria ampla; resposta depende de duração, intensidade e recovery','CD,RD,UT,FR','não é mecanismo único','Todas','A-B','S01,S03,S04,S09');
INSERT INTO "training_types" VALUES('SIT','SIT / SIIT','sprint','10–45 s all-out/near-all-out','frequentemente 1–4 min ou mais','9–10','Potência máxima, recrutamento neuromuscular e forte estímulo anaeróbio; não atribuir automaticamente a um limitador cardiorrespiratório','UT,FR,ME','não autoatribuir como ''respiratório'' ou ''cardíaco''','Bike/Row/Ski/Run','B','S03,S04,S09');
INSERT INTO "training_types" VALUES('RST','Repeated Sprint / RST','sprint_repeat','~20 s–1 min por repetição','curta/moderada, frequentemente suficiente para preservar qualidade','8–10','Repetição de potência/sprint com recuperação incompleta ou específica','UT,FR,ME','não usar como sinônimo de SIT ou HIIT','Bike/Row/Ski/Run','B','S03,S04,S09');
INSERT INTO "training_types" VALUES('OU','Over/Under','mixed_threshold','blocos de minutos; sem duração fixa universal','parcial/curta','6–8','Manipular transições e recuperação parcial em torno de uma intensidade sustentada','CD,RD,UT,FR','não usar o nome como diagnóstico','Bike/Row/Ski/Run','B','S01,S06,S08');
INSERT INTO "training_types" VALUES('IMT','IMT / treinamento inspiratório','respiratory_auxiliary','sessão separada do treino cíclico; protocolo depende do dispositivo','conforme protocolo específico','varia','Força/endurance dos músculos inspiratórios; intervenção complementar','RD','não usar como substituto de treino cíclico ou diagnóstico VST/MOXY','Auxiliar','B','S05,S08');
INSERT INTO "training_types" VALUES('ISO','Isocapnic / estratégia ventilatória','respiratory_auxiliary','curto ou em blocos conforme protocolo','conforme protocolo','varia','Consciência, coordenação, controle de frequência/profundidade e tolerância ventilatória','RD','não confundir com zona de potência do treino','Auxiliar','B','S08');
INSERT INTO "sqlite_sequence" VALUES('monitoring_rules',6);
